 require_once(__DIR__ . '/../app/init.php'); class util_setup { protected $path; protected $listen = []; protected $iniAliases = []; protected $apps; protected $findedTasks = []; protected $iniHttpPort; protected $iniSslPort; protected $iniEnableSsl; function __construct () { Cache::disable(); $this->path = realpath(__DIR__ . '/../../..'); $this->apps = loadAppConfigs(true); } public function createHttpdConf () { $this->createHttpdVarsConf(); $this->createHttpdVHostsConf(); } public function createFrontEndAppsJson ($path) { $apps = new \stdClass(); foreach ($this->apps as $name => $from) { if ($name !== '*') { $to = $apps->{$name} = new \stdClass(); $copyProp = function ($prop) use ($from, $to) { if (property_exists($from, $prop)) $to->{$prop} = $from->{$prop}; }; $copyProp('version'); $copyProp('widget'); $copyProp('serverConfig'); $copyProp('script'); $copyProp('theme'); $copyProp('css'); } } file_put_contents($path, json_encode($apps, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)); } protected function addDirs ($array, &$dirs, &$files) { foreach ($array as $value) { if (safe_strpos($value, '.') === false) { $value .= '/'; if (!isset($dirs[$value])) { $dirs[$value] = true; } } else { if (!isset($files[$value])) { $files[$value] = true; } } } } protected function addScripts (&$array, $app) { if (isset($app->script)) { $array = array_merge($array, array_fill_keys($app->script, true)); } if (isset($app->addScripts)) { $array = array_merge($array, array_fill_keys($app->addScript, true)); } } protected function removeSameDirs (&$exclude, $access) { foreach ($access as $key => $value) { if (isset($exclude[$key])) { unset($exclude[$key]); } } } protected function createHttpdVarsConf () { $path = $this->path; $conf = "# Файл сгенерирован автоматически из ini.bat, не редактируйте его!\n"; $iniBat = self::getEncodedFileContents("$path/cfg/ini.bat"); $matches = null; $count = preg_match_all('/^(?:\s*set)\s+(\w+)=(.*)/im', $iniBat, $matches); $count = $count ?: 0; for ($i = 0; $i < $count; $i++) { $value = trim($matches[2][$i]); if ($value) { $name = trim($matches[1][$i]); if ($name === 'ServiceName') continue; if ($name === 'ServerName') $name = 'SrvName'; $conf .= "\nDefine $name $value"; if ($name === 'ServerPort') { $this->listen[$value] = true; $this->iniHttpPort = $value; } if ($name === 'SSLPort') { $this->listen[$value] = true; $this->iniSslPort = $value; } if ($name === 'EnableSSL') { $this->iniEnableSsl = ($value == 'true' ? true : false); } if ($name === 'SrvName' || $name === 'DomainName') { $this->iniAliases[] = $value; } } } if (empty($this->iniEnableSsl) && !empty($this->iniSslPort)) { unset($this->listen[$this->iniSslPort]); $this->iniSslPort = null; } file_put_contents("$path/cfg/httpd-vars.conf", $conf); } protected function createHttpdVHostsConf () { $path = $this->path; $apps = $this->apps; $iniAliases = implode('|', $this->iniAliases); $customPorts = []; $conf = "# Файл сгенерирован автоматически из vhosts.ini, не редактируйте его!"; $vhostsTxt = self::getEncodedFileContents("$path/cfg/vhosts.ini"); $matches = null; $count = preg_match_all('/^[ \t]*([^#=\r\n]*)=[ \t]*([^\r\n#]+)/im', $vhostsTxt, $matches); $count = $count ?: 0; for ($i = 0; $i < $count; $i++) { $params = trim($matches[1][$i]); $params = safe_explode(',', preg_replace('/[\s,;]+/', ',', $params)); $params = str_replace('\\', '/', $params); $tasks = trim(strtolower($matches[2][$i])); $tasks = safe_explode(',', preg_replace('/[\s,;]+/', ',', $tasks)); $protocol = null; $ports = []; $aliases = []; foreach ($params as $s) { if (!empty($s)) { $s = strtolower($s); if ($s === 'https' || $s === 'ssl' || $s === 'tls') { $protocol = $protocol ?: 'ssl'; } else if ($s === 'http') { $protocol = $protocol ?: 'http'; } else if ($s === '*') { $aliases[] = '.*'; } else if (safe_strpos($s, '.') !== false) { $aliases[] = $s; } else if (!preg_match('/[^\d]/', $s)) { $ports[] = $s; if ($s === '443') { $protocol = 'ssl'; } else if ($s === '80') { $protocol = 'http'; } } } } $index = 0; foreach ($ports as $port) { if (!isset($this->listen[$port])) { if (++$index === 1) $conf .= "\n"; $conf .= "\nListen $port"; $this->listen[$port] = true; } if (!isset($customPorts[$port])) { $customPorts[$port] = true; } } for ($pass = 1; $pass <= 2; $pass++) { $portsText = null; if (empty($ports)) { if ($pass === 1 && !empty($this->iniHttpPort) && $protocol !== 'ssl') { $portsText = '*:' . $this->iniHttpPort; } else if ($pass === 2 && !empty($this->iniSslPort) && $protocol !== 'http') { $portsText = '*:' . $this->iniSslPort; $protocol = 'ssl'; } } else if ($pass === 1) { $portsText = '*:' . implode(' *:', $ports); } if (empty($portsText)) { continue; } $conf .= "\n\n<VirtualHost " . $portsText . '>'; if ($protocol === 'ssl') { $conf .= "\n\tSSLEngine On"; } if (!empty($aliases)) { $conf .= "\n\tServerAlias " . implode(' ', $aliases); } $conf .= "\n\tHeader set Access-Control-Allow-Origin \"*\"\n"; $conf .= "\n\tHeader set Access-Control-Allow-Headers \"x-requested-with, Content-Type, origin, authorization, accept, client-security-token\"\n"; $conf .= "\n\tRewriteOptions Inherit\n"; $accessDirs = []; $accessFiles = []; $excludeDirs = []; $excludeFiles = []; $scripts = []; foreach ($tasks as $taskName) { if (!isset($apps->{$taskName})) { throw new Exception("Ошибка! Неверное название задачи \"$taskName\"."); } $task = $apps->{$taskName}; if (!empty($task->access)) { $this->addDirs(is_array($task->access) ? $task->access : safe_explode(',', $task->access), $accessDirs, $accessFiles); } if (!empty($task->exclude)) { $this->addDirs(is_array($task->exclude) ? $task->exclude : safe_explode(',', $task->exclude), $excludeDirs, $excludeFiles); } if (isset($task->apps)) { $this->addScripts($scripts, $task); } } $this->removeSameDirs($excludeDirs, $accessDirs); $this->removeSameDirs($excludeFiles, $accessFiles); if (!empty($accessDirs)) { $list = implode('|', array_keys($accessDirs)); $conf .= "\n\t<Directory ~ \"($list)\">"; $conf .= "\n\t\tOptions Includes FollowSymLinks"; $conf .= "\n\t\tRequire all granted"; $conf .= "\n\t</Directory>"; } if (!empty($accessFiles)) { $list = implode('|', array_keys($accessFiles)); $conf .= "\n\t<Files ~ \"($list)\">"; $conf .= "\n\t\tRequire all granted"; $conf .= "\n\t</Files>"; } if (!empty($scripts)) { $list = implode('|', array_keys($scripts)); $conf .= "\n\t<Location ~ \"($list)\">"; $conf .= "\n\t\tRequire all granted"; $conf .= "\n\t</Location>"; } if (!empty($excludeDirs)) { $list = implode('|', array_keys($excludeDirs)); $conf .= "\n\t<Directory ~ \"($list)\">"; $conf .= "\n\t\tRequire all denied"; $conf .= "\n\t</Directory>"; } if (!empty($excludeFiles)) { $list = implode('|', array_keys($excludeFiles)); $conf .= "\n\t<Files ~ \"($list)\">"; $conf .= "\n\t\tRequire all denied"; $conf .= "\n\t</Files>"; } $conf .= "\n</VirtualHost>"; } } file_put_contents("$path/cfg/httpd-vhosts.conf", $conf); } static function getEncodedFileContents ($file) { $res = file_get_contents($file); if (mb_detect_encoding($res, 'UTF-8', true) === false) { if (mb_detect_encoding($res, 'CP866', true) === false) { $res = mb_convert_encoding($res, 'UTF-8', 'CP1251'); } else { $res = mb_convert_encoding($res, 'UTF-8', 'CP866'); } } else if (substr($res, 0, 3) === (chr(0xEF).chr(0xBB).chr(0xBF))) { $res = substr($res, 3); } return $res; } static function isSsl ($s) { $s = strtolower($s); return $s === 'https' || $s === 'ssl' || $s === 'tls'; } } handleJsonRpc('util_setup');